import React from 'react';
import { ChevronLeft, Triangle, ArrowUp, ArrowDown } from 'lucide-react';
import {
  AreaChart,
  Area,
  XAxis,
  YAxis,
  CartesianGrid,
  ResponsiveContainer,
  Dot
} from 'recharts';

// --- データ定義 ---
const data = [
  { name: '第1号', blue: 1.2, orange: 2.0 },
  { name: '第2号', blue: 1.5, orange: 1.8 },
  { name: '第2号', blue: 1.1, orange: 2.3 },
  { name: '第3号', blue: 1.5, orange: 2.0 },
  { name: '第3号', blue: 1.1, orange: 1.8 },
  { name: '第4号', blue: 2.0, orange: 2.6 },
  { name: '第5号', blue: 1.5, orange: 2.1 },
  { name: '第5号', blue: 2.2, orange: 2.8 },
];

// --- サブコンポーネント ---

// 上部の4つのステータスカード
const StatCard = ({ title, value, unit, trend, colorClass }: any) => (
  <div className={`${colorClass} rounded-sm p-2 flex flex-col justify-between aspect-square w-full`}>
    <span className="text-[10px] text-white/80 font-medium whitespace-nowrap">{title}</span>
    <div className="flex items-baseline justify-center gap-0.5">
      <span className="text-xl font-bold italic">{value}</span>
      <span className="text-[10px]">{unit}</span>
      {trend === 'up' && <ArrowUp size={12} className="text-red-500 fill-red-500 ml-1" />}
      {trend === 'down' && <ArrowDown size={12} className="text-red-500 fill-red-500 ml-1" />}
      {trend === 'triangle' && <Triangle size={8} className="text-emerald-400 fill-emerald-400 ml-1" />}
    </div>
  </div>
);

// 下部の履歴行
const HistoryRow = ({ issue, rank }: { issue: string; rank: string }) => (
  <div className="flex justify-between items-center py-2 border-b border-gray-700/50">
    <span className="text-gray-300 text-sm font-medium">{issue}</span>
    <div className="flex items-baseline gap-0.5">
      <span className="text-lg font-bold italic">{rank}</span>
      <span className="text-[10px] font-bold">位</span>
    </div>
  </div>
);

// --- メインコンポーネント ---
export default function SeriesDetailView() {
  return (
    <div className="bg-[#1b2230] text-white min-h-screen w-full max-w-md mx-auto p-4 font-sans">
      {/* ヘッダー */}
      <header className="flex items-center justify-between mb-6">
        <ChevronLeft className="text-gray-400" size={24} />
        <h1 className="text-xl font-bold tracking-[0.2em]">ONE PIECE</h1>
        <div className="w-6" />
      </header>

      {/* ステータスセクション */}
      <div className="grid grid-cols-4 gap-2 mb-8">
        <StatCard title="最新順位" value="1" unit="位" colorClass="bg-[#2a5496]" />
        <StatCard title="平均順位" value="2.4" unit="位" trend="triangle" colorClass="bg-[#2d5a50]" />
        <StatCard title="最高順位" value="1" unit="位" trend="up" colorClass="bg-[#252b39] border border-gray-700" />
        <StatCard title="最低順位" value="6" unit="位" trend="down" colorClass="bg-[#252b39] border border-gray-700" />
      </div>

      {/* グラフセクション */}
      <section className="mb-8">
        <h2 className="text-sm font-bold mb-4 border-b border-gray-700 pb-1">順位推移</h2>
        <div className="h-48 w-full mt-4">
          <ResponsiveContainer width="100%" height="100%">
            <AreaChart data={data} margin={{ top: 10, right: 10, left: -30, bottom: 0 }}>
              <defs>
                <linearGradient id="colorBlue" x1="0" y1="0" x2="0" y2="1">
                  <stop offset="5%" stopColor="#60a5fa" stopOpacity={0.3}/>
                  <stop offset="95%" stopColor="#60a5fa" stopOpacity={0}/>
                </linearGradient>
                <linearGradient id="colorOrange" x1="0" y1="0" x2="0" y2="1">
                  <stop offset="5%" stopColor="#fb923c" stopOpacity={0.3}/>
                  <stop offset="95%" stopColor="#fb923c" stopOpacity={0}/>
                </linearGradient>
              </defs>
              <CartesianGrid strokeDasharray="0" vertical={false} stroke="#334155" />
              <XAxis 
                dataKey="name" 
                axisLine={false} 
                tickLine={false} 
                tick={{ fill: '#94a3b8', fontSize: 12 }}
                interval={1}
              />
              <YAxis reversed domain={[1, 3]} hide />

              {/* オレンジのライン */}
              <Area
                type="monotone"
                dataKey="orange"
                stroke="#f87171"
                strokeWidth={2}
                fillOpacity={1}
                fill="url(#colorOrange)"
                dot={{ r: 4, fill: '#fff', stroke: '#f87171', strokeWidth: 2 }}
              />
              {/* ブルーのライン */}
              <Area
                type="monotone"
                dataKey="blue"
                stroke="#60a5fa"
                strokeWidth={2}
                fillOpacity={1}
                fill="url(#colorBlue)"
                dot={{ r: 4, fill: '#fff', stroke: '#60a5fa', strokeWidth: 2 }}
              />
            </AreaChart>
          </ResponsiveContainer>
        </div>
      </section>

      {/* 号別順位リスト */}
      <section>
        <h2 className="text-sm font-bold mb-2">号別順位</h2>
        <div className="flex flex-col">
          <HistoryRow issue="第10号" rank="1" />
          <HistoryRow issue="第9号" rank="2" />
          <HistoryRow issue="第8号" rank="3" />
        </div>
      </section>
    </div>
  );
}
